import {works,experiences,notes} from '../desk-data.mjs';
import {education} from '../desk-background.mjs';
import {organisations,credentials,experienceTags} from '../desk-affiliations.mjs';
import {music,desk} from '../desk-config.mjs';

export const directions={
 bench:{name:'正在使用的工作台',en:'Active workbench',blurb:'先看桌上的东西，再在旁边翻开。',structure:'物件入口 / 常驻侧边阅读',risk:'场景最自然，但多内容会依赖阅读区；要避免把每个物件都变成按钮。'},
 drawer:{name:'打开的抽屉',en:'Open drawer',blurb:'按去过的地方收着，一起翻出来。',structure:'组织分组 / 多条记录同时展开',risk:'收纳逻辑最明确，但这张偏复古，也容易让网站显得过于规整。'},
 editorial:{name:'编辑桌面',en:'Editorial surface',blurb:'文字直接进入画面，内容往下展开。',structure:'连续目录 / 行内阅读',risk:'阅读与扩展最稳，颜色更现代；工作桌的沉浸感相对弱。'}
};
const app=document.querySelector('#app'),audio=document.querySelector('#music');
let lang='zh',filter='all',query='',musicError='';
const chosen=new URLSearchParams(location.search).get('view');
const view=Object.hasOwn(directions,chosen??'')?chosen:null;
const t=(zh,en)=>lang==='zh'?zh:en;
const pick=o=>o?.[lang]??o??'';
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paragraphs=a=>(Array.isArray(a)?a:[]).map(p=>`<p>${h(p)}</p>`).join('');
const link=(href,text,cls='')=>`<a class="${cls}" href="${h(href)}">${h(text)}</a>`;
const route=()=>location.hash.slice(1).split('/').filter(Boolean);
const asset=name=>`../desk-assets/${name}`;
const labels=()=>({works:t('论文与项目','Papers & projects'),background:t('学习与经历','Studies & experiences'),notes:t('随手写的','Notes')});
const pageName=page=>labels()[page]??({work:t('论文条目','Paper entry'),paper:t('全文阅读','Paper reader'),note:t('随笔','Note'),experience:t('经历','Experience')}[page])??t('桌面','Desk');
function musicUI(){return `<button type="button" class="music-toggle" data-music aria-pressed="${!audio.paused}">${audio.paused?t('播放','Play'):t('暂停','Pause')} · ${h(music.title)}</button><small class="music-caption">${h(music.artist)} · ${t('试听片段','Preview')}${musicError?' · '+h(musicError):''}</small>`;}
function top(){return `<header class="site-header">${link('#home','Tin-Yeh Huang','wordmark')}<nav aria-label="${t('网站导航','Site navigation')}">${Object.entries(labels()).map(([k,v])=>link('#'+k,v)).join('')}</nav><div class="utilities"><button data-language>${lang==='zh'?'EN':'中文'}</button>${link('./',t('比较方案','Compare'))}</div></header>`;}
function scene(){return `<section class="scene" aria-label="${t('物件桌面','Object desk')}"><img class="scene-image" src="assets/${view}.jpg" width="1488" height="1060" alt="${h(t('生成的场景示意：文件、笔记本、卡尺与播放器；不是个人作品或真实桌面照片。','Generated scene study with documents, notebook, caliper and player; not a photograph of personal work.'))}"><div class="intro"><p class="eyebrow">${t('个人网站','Personal website')}</p><h1>Tin-Yeh<br class="name-break"> Huang</h1><p class="intro-study">${h(pick(desk.intro.study))}</p><p class="intro-text">${h(pick(desk.intro.text))}</p></div><div class="object-links">${link('#background',labels().background,'object-label label-background')}${link('#works',labels().works,'object-label label-works')}${link('#notes',labels().notes,'object-label label-notes')}<div class="object-label label-music">${musicUI()}</div></div></section>`;}
function home(){return `${scene()}<section class="below-desk"><div><p class="eyebrow">${t('这阵子','Lately')}</p>${link('#note/website',t('还在改这个网站。','Still working on this site.'))}<p>${t('一些东西先放着，慢慢再补。','Keeping a few things here, adding to them gradually.')}</p></div><div class="home-index"><p class="eyebrow">${t('留在这里的两条记录','Two records kept here')}</p>${link('#work/heatwave',t('2026 · 热浪风险研究','2026 · Cascading heatwave risks'))}${link('#note/simple',t('草稿 · 简约就一定好吗','Draft · Is simpler always better?'))}</div></section><footer class="prototype-note">${t('设计试验 · 场景物件为生成素材，内容沿用现有记录。','Design trial · Generated scene objects, existing content records.')} ${link('./',t('返回三方案比较','Compare the three directions'))}</footer>`;}
function studyRows(list=education){return list.map(e=>`<article class="study-row"><time>${h(e.date)}</time><div><h3>${h(pick(e.name))}</h3><p>${h(pick(e.course))} · ${h(pick(e.status))}</p><small>${h(pick(e.extra))}</small></div></article>`).join('');}
function recordBody(e){const related=works.filter(w=>w.experience===e.id || e.related?.includes(w.id));return `<div class="entry-body">${paragraphs(pick(e.body))}${related.length?`<p class="related-label">${t('这段经历中的内容','From this period')}</p>${related.map(w=>link('#work/'+w.id,pick(w.title),'related-link')).join('')}`:''}</div>`;}
function record(e,open=false){return `<details class="record" data-record="${e.id}" ${open?'open':''}><summary><time>${h(e.date)}</time><span><strong>${h(pick(e.role))}</strong><span class="record-org">${h(pick(e.name))}</span></span><span class="expand-label">${t('展开','Read')}</span></summary>${recordBody(e)}</details>`;}
function credentialRows(){return `<details class="credentials"><summary>${t('会员身份与专业证书','Memberships & certification')}</summary><p class="muted">${t('依据 CV 记录；会员身份不代表任职，公开凭证尚未收录。','From the CV; memberships are not appointments. Public credentials are not yet included.')}</p>${credentials.map(c=>`<div class="credential"><time>${h(c.date)}</time><span><strong>${h(c.issuer)}</strong><br>${h(pick(c.title))}</span><small>${c.kind==='membership'?t('会员','Membership'):t('证书','Certification')}</small></div>`).join('')}</details>`;}
function filterUI(){const filters=[['all',t('所有经历','All records')],['research',t('研究','Research')],['work',t('实习与工作','Work')],['service',t('服务与代表','Service')],['projects',t('项目参与','Programmes')]];return `<div class="filters" role="group" aria-label="${t('经历分类','Filter experiences')}">${filters.map(([id,name])=>`<button data-filter="${id}" aria-pressed="${filter===id}">${name}</button>`).join('')}</div>`;}
function background(){if(view==='drawer')return `<div class="section-heading"><p class="eyebrow">${t('去过的地方','Places along the way')}</p><h1>${labels().background}</h1><p>${t('同一个地方，不止一段经历。可以同时打开几个。','More than one experience at a place. Open several together.')}</p></div><div class="organisation-folders">${[...organisations.filter(o=>o.study?.length),...organisations.filter(o=>!o.study?.length)].map((o,i)=>`<details class="org-folder" ${i===0?'open':''}><summary>${o.mark?`<img src="${asset('pins/'+o.mark)}" width="48" height="48" alt="">`:''}<span><strong>${h(pick(o.name))}</strong><small>${(o.study?.length??0)+o.records.length} ${t('条记录','records')}</small></span></summary><div class="org-content">${o.study?.length?studyRows(education.filter(e=>o.study.includes(e.id))):''}${o.records.map(id=>record(experiences.find(e=>e.id===id))).join('')}</div></details>`).join('')}<details class="org-folder"><summary>${t('跨机构审稿记录','Cross-institution peer review')}</summary>${record(experiences.find(e=>e.id==='academic-reviewing'))}</details></div>${credentialRows()}`;
 return `<div class="section-heading"><p class="eyebrow">${t('关于我的一些记录','A few records about me')}</p><h1>${labels().background}</h1></div><section><h2>${t('先从学习说起','Studies first')}</h2>${studyRows()}</section><section class="experience-section"><h2>${t('参与过的事情','Things I have taken part in')}</h2>${filterUI()}<div class="records">${experiences.filter(e=>filter==='all'||experienceTags[e.id]?.includes(filter)).map(e=>record(e)).join('')}</div><p class="muted">${t('任期沿用 CV；不把仍在进行的参与写成已经结束的经历。','Terms are taken from the CV, including ongoing involvement.')}</p></section>${credentialRows()}`;
}
function sourceLinks(w){return `<div class="source-links">${w.links?.map(([name,url])=>`<a href="${h(url)}" target="_blank" rel="noopener noreferrer">${h(name)}</a>`).join('')??''}</div>`;}
function workBody(w){return `<article class="work-body"><p class="muted">${h(w.fullTitle)}</p>${paragraphs(pick(w.body))}<p class="version">${h(pick(w.version))}</p>${w.pdf?`<div class="paper-preview"><img src="${asset(w.thumb)}" alt="${h(w.fullTitle)} ${t('首页','first page')}" loading="lazy"><div><p>${h(w.pages)} ${t('页 · 本地预印本','pages · Local preprint')}</p>${link('#paper/'+w.id,t('在站内阅读 PDF','Read PDF here'),'primary-link')}</div></div>`:''}${sourceLinks(w)}${w.experience?link('#experience/'+w.experience,t('相关经历','Related experience'),'related-link'):''}</article>`;}
function workList(){const found=works.filter(w=>[pick(w.title),w.fullTitle,w.context].join(' ').toLowerCase().includes(query.toLowerCase()));return `<div class="section-heading"><p class="eyebrow">${t('做过、参与过，也还在整理','Made, joined, still being gathered')}</p><h1>${labels().works}</h1><label class="search-label">${t('找一个条目','Find an entry')}<input type="search" name="search" value="${h(query)}" placeholder="${t('标题或关键词','Title or keyword')}"></label></div><div class="work-list" aria-live="polite">${found.map((w,i)=>view==='editorial'?`<details class="editorial-entry"><summary><span class="entry-number">${String(i+1).padStart(2,'0')}</span><span><strong>${h(pick(w.title))}</strong><small>${h(w.context)}</small></span><time>${w.year}</time></summary>${workBody(w)}</details>`:`<a class="work-row" href="#work/${w.id}">${w.thumb?`<img src="${asset(w.thumb)}" alt="" loading="lazy">`:`<span class="entry-number">${String(i+1).padStart(2,'0')}</span>`}<span><strong>${h(pick(w.title))}</strong><small>${h(w.context)}</small><p>${h(pick(w.summary))}</p></span><time>${w.year}</time></a>`).join('')||`<p>${t('没有找到，可以换个词。','No matches. Try another word.')}</p>`}</div>`;}
function notesList(){return `<div class="section-heading"><p class="eyebrow">${t('还没写定','Not quite finished')}</p><h1>${labels().notes}</h1></div>${notes.map(n=>`<a class="note-row" href="#note/${n.id}"><time>${h(n.date)}</time><h2>${h(pick(n.title))}</h2><p>${h(pick(n.paragraphs)[0])}</p><small>${t('草稿 · 据网站讨论整理，待本人修改','Draft · Edited from website discussions, awaiting revision')}</small></a>`).join('')}`;}
function contents(page,id){if(page==='background')return background();if(page==='works')return workList();if(page==='notes')return notesList();if(page==='work'){const w=works.find(w=>w.id===id);if(w)return `${link('#works',t('返回论文与项目','Back to papers & projects'),'back-link')}<div class="section-heading"><p class="eyebrow">${h(w.year)} · ${h(w.context)}</p><h1>${h(pick(w.title))}</h1></div>${workBody(w)}`;}
 if(page==='paper'){const w=works.find(w=>w.id===id&&w.pdf);if(w)return `${link('#work/'+id,t('返回条目','Back to entry'),'back-link')}<h1>${h(pick(w.title))}</h1><p class="version">${h(pick(w.version))}</p><p>${link(asset(w.pdf),t('单独打开 PDF','Open PDF separately'),'primary-link')} · <a href="${asset(w.pdf)}" download>${t('下载 PDF','Download PDF')}</a></p><p class="muted reader-note">${t('逐页图像预览；文字检索与复制请打开原 PDF。','Page-image preview; open the original PDF for text search and copying.')}</p><div class="page-toolbar"><button data-paper-step="-1" disabled>${t('上一页','Previous')}</button><label>${t('页码','Page')} <select id="paper-page" data-paper="${w.id}">${Array.from({length:w.pages},(_,i)=>`<option value="${i+1}">${i+1} / ${w.pages}</option>`).join('')}</select></label><button data-paper-step="1">${t('下一页','Next')}</button></div><img class="page-image" id="paper-image" src="assets/papers/${w.id}-01.jpg" alt="${h(w.fullTitle)} — ${t('第 1 页','Page 1')}">`;}
 if(page==='note'){const n=notes.find(n=>n.id===id);if(n)return `${link('#notes',t('返回随笔','Back to notes'),'back-link')}<article class="note-reading"><p class="eyebrow">${h(n.date)} · ${t('草稿','Draft')}</p><h1>${h(pick(n.title))}</h1>${paragraphs(pick(n.paragraphs))}<small>${t('依据网站讨论整理，待本人修改；不是已发表文章。','Edited from website discussions; not a published essay.')}</small></article>`;}
 if(page==='experience'){const e=experiences.find(e=>e.id===id);if(e)return `${link('#background',t('返回经历','Back to experiences'),'back-link')}<p class="eyebrow">${h(e.date)}</p><h1>${h(pick(e.name))}</h1><h2>${h(pick(e.role))}</h2>${recordBody(e)}`;}
 return `<h1>${t('这里还没有内容','Nothing here yet')}</h1>${link('#home',t('回到桌面','Back to the desk'))}`;}
function interior(page,id){const navigation=Object.entries(labels()).map(([key,name])=>link('#'+key,name,(key===page||page==='work'&&key==='works'||page==='note'&&key==='notes'||page==='experience'&&key==='background')?'active':'')).join('');return `<div class="interior"><aside class="context-rail">${link('#home',t('回到桌面','Back to the desk'),'return-desk')}<img src="assets/${view}.jpg" alt="" class="context-image"><nav aria-label="${t('内容分组','Collections')}">${navigation}</nav><div class="rail-music">${musicUI()}</div></aside><article class="reading" id="reading" tabindex="-1">${contents(page,id)}</article></div>`;}
function compare(){return `<main id="main" class="comparison"><header><p class="eyebrow">DESIGN TRIAL / 2026.09</p><h1>同一份内容，<br>三个进入方式。</h1><p class="compare-intro">先比较场景和阅读，不急着定稿。三个版本都能打开经历、论文与随笔；当前场景是生成图像，不是可拖动物件的实时 3D。</p></header><div class="comparison-grid">${Object.entries(directions).map(([id,d],i)=>`<article><a class="preview-link" href="?view=${id}#home"><img src="assets/${id}.jpg" alt="${d.name}" width="1488" height="1060"><span>打开 demo</span></a><p class="eyebrow">${String(i+1).padStart(2,'0')} / ${d.en}</p><h2>${d.name}</h2><p>${d.blurb}</p><small>${d.structure}</small><p class="tradeoff">${d.risk}</p><div class="compare-links">${link('?view='+id+'#home','首页')}${link('?view='+id+'#background','经历内页')}${link('?view='+id+'#works','论文与项目')}</div></article>`).join('')}</div><section class="test-guide"><h2>用同样的动作试一遍</h2><ol><li>刚打开时，是否知道这是谁的网站、哪里可以点？</li><li>找到 PolyU 的学习与学生代表记录，再看另一段经历。</li><li>打开一篇论文，阅读 PDF，再回到原来的内容。</li><li>缩窄窗口，观察物件与阅读是否仍然成立。</li></ol><p>暂不测试：物体自由拖动、摄像机旋转、实时光影、最终个人文案。没有把生成的材质图收成“个人作品”。</p><p>这批不改动旧版 <a href="../table/">table</a> 或 <a href="../desk.html">desk</a>。</p></section></main>`;}
function render(focus=false){document.documentElement.lang=lang==='zh'?'zh-Hans':'en';document.body.dataset.direction=view??'compare';const [page='home',id]=route();document.body.dataset.page=page;document.title=view?`${pageName(page)} · ${directions[view].name} · Tin-Yeh Huang`:'三个桌面 · 设计试验';app.innerHTML=view?`${top()}<main id="main">${page==='home'?home():interior(page,id)}</main>`:compare();syncMusic();if(focus){document.querySelector('#reading')?.focus({preventScroll:true});window.scrollTo(0,0);}}
app.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;if(button.hasAttribute('data-language')){lang=lang==='zh'?'en':'zh';render();return;}if(button.dataset.filter){filter=button.dataset.filter;const y=scrollY;render();document.querySelector(`[data-filter="${filter}"]`)?.focus({preventScroll:true});window.scrollTo(0,y);return;}if(button.hasAttribute('data-music')){musicError='';if(audio.paused){if(!audio.src)audio.src=music.src;audio.volume=music.volume;try{await audio.play();}catch{musicError=t('未能播放，可稍后再试','Could not play; try again');syncMusic();}}else audio.pause();}});
app.addEventListener('input',event=>{if(event.target.name==='search'){query=event.target.value;const start=event.target.selectionStart;document.querySelector('.reading').innerHTML=workList();const input=document.querySelector('[name="search"]');input.focus({preventScroll:true});try{input.setSelectionRange(start,start);}catch{}}});
function syncMusic(){let globalButton=document.querySelector('.header-music');if(!globalButton&&document.querySelector('.utilities')){globalButton=document.createElement('button');globalButton.className='music-toggle header-music';globalButton.dataset.music='';document.querySelector('.utilities').prepend(globalButton);}if(globalButton)globalButton.hidden=audio.paused;document.querySelectorAll('.music-toggle').forEach(b=>{b.textContent=`${audio.paused?t('播放','Play'):t('暂停','Pause')} · ${music.title}`;b.setAttribute('aria-pressed',String(!audio.paused));});document.querySelectorAll('.music-caption').forEach(c=>c.textContent=`${music.artist} · ${t('试听片段','Preview')}${musicError?' · '+musicError:''}`);}
for(const e of ['play','pause','ended'])audio.addEventListener(e,syncMusic);
audio.addEventListener('error',()=>{musicError=t('试听不可用','Preview unavailable');syncMusic();});
function updatePaper(value){const select=document.querySelector('#paper-page');if(!select)return;const w=works.find(w=>w.id===select.dataset.paper);const number=Math.max(1,Math.min(w.pages,Number(value)||1));select.value=String(number);const img=document.querySelector('#paper-image');img.src=`assets/papers/${w.id}-${String(number).padStart(2,'0')}.jpg`;img.alt=`${w.fullTitle} — ${t('页','Page')} ${number}`;document.querySelector('[data-paper-step="-1"]').disabled=number===1;document.querySelector('[data-paper-step="1"]').disabled=number===w.pages;}
app.addEventListener('change',event=>{if(event.target.id==='paper-page')updatePaper(event.target.value);});
app.addEventListener('click',event=>{const button=event.target.closest('[data-paper-step]');if(button)updatePaper(Number(document.querySelector('#paper-page').value)+Number(button.dataset.paperStep));});
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();const main=document.querySelector('#main');main?.setAttribute('tabindex','-1');main?.focus();});
window.addEventListener('hashchange',()=>{filter='all';query='';render(true);syncMusic();});
render();
syncMusic();
